impl Engine {
    fn new(
        global: &Arc<GlobalSourceData>,
        options: &PipelineOptions,
        ambient_global_files: &[Utf8PathBuf],
        named_types: &Arc<NamedTypeIndex>,
        layer: Option<Arc<DependencyLayer>>,
