            if missing.is_empty() {
                let resolved = Arc::new(Resolved { entry, diagnostics, depends_on });
                return Some(lazy.memo.entry(id.clone()).or_insert(resolved).clone());
            }
            self.grow(options, lazy, &missing);
        }
    }

